create table veranolink.vl_call_types (
    id_vl_call_type number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    call_name       varchar2(10 char),
    created_date    timestamp(6) default systimestamp
);

alter table veranolink.vl_call_types
    add constraint vl_call_types_pk primary key ( id_vl_call_type )
        using index enable;


